def fires(b):
    # opponent's last stone sits horizontally next to my previous stone
    if len(b.moves) < 2:
        return False
    c = b.last_col
    r = b.last_row
    pc = b.moves[-2]
    pr = b.heights[pc] - 1
    if pc == c:
        pr = pr - 1
    return pr == r and abs(pc - c) == 1

def level(b):
    return 6 if fires(b) else 0

def fires(b):
    # early game, I own a bottom corner cell, and the center bottom is not mine
    edge = (b.grid[0][0] == 1) + (b.grid[0][6] == 1)
    return b.ply <= 12 and edge >= 1 and b.grid[0][3] != 1

def level(b):
    if not fires(b):
        return 0
    edge = (b.grid[0][0] == 1) + (b.grid[0][6] == 1)
    return 4 + 2 * edge
